/*
 * Helpers to explore 3D representations of infrastructures generated by RacksDB
 * in glTF format. The scene graph follows RacksDB database structure (room → row →
 * rack → equipment). Every node representing a database object is named after this
 * object and has its metadata in extras (userData in three.js), with the category
 * of object in category key. Geometry is attached to unnamed child nodes, with a
 * part key in their extras.
 */

import { Box3, Quaternion, Vector3 } from 'three'
import type { Material, Mesh, MeshStandardMaterial, Object3D } from 'three'
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js'
import type { GLTF } from 'three/examples/jsm/loaders/GLTFLoader.js'

export const EQUIPMENT_CATEGORIES = new Set(['node', 'storage', 'network', 'misc'])

/* Subset of GLTF object used to retrieve original names of glTF nodes. */
export type GLTFNames = { parser: Pick<GLTF['parser'], 'associations' | 'json'> }

export interface Focus {
  center: Vector3
  size: Vector3
  radius: number
  /* Azimuth in radians around the vertical axis of the direction faced by the
   * racks doors, 0 being +Z. */
  azimuth: number
}

export function parseGlb(data: ArrayBuffer): Promise<GLTF> {
  return new Promise((resolve, reject) => {
    new GLTFLoader().parse(data, '', resolve, reject)
  })
}

export function isEquipment(object: Object3D): boolean {
  return EQUIPMENT_CATEGORIES.has(object.userData?.category)
}

/* Return true if the object and all its ancestors are visible. */
export function isVisible(object: Object3D): boolean {
  let current: Object3D | null = object
  while (current) {
    if (!current.visible) return false
    current = current.parent
  }
  return true
}

/* Return the closest ancestor of object (including itself) representing an
 * equipment, or null if not found. */
export function findEquipment(object: Object3D | null): Object3D | null {
  let current = object
  while (current) {
    if (isEquipment(current)) {
      return current
    }
    current = current.parent
  }
  return null
}

/* Return the name of the glTF node of the given object. Three.js sanitizes object
 * names (ex: dots are removed), the original name is retrieved from the glTF
 * document when possible. */
export function originalName(gltf: GLTFNames, object: Object3D): string {
  const index = gltf.parser.associations.get(object)?.nodes
  if (index !== undefined) {
    const name = gltf.parser.json.nodes?.[index]?.name
    if (name) {
      return name
    }
  }
  return object.name
}

/* Return map of equipment objects in the scene indexed by their original names. */
export function indexEquipment(gltf: GLTFNames, root: Object3D): Map<string, Object3D> {
  const result = new Map<string, Object3D>()
  root.traverse((object) => {
    if (isEquipment(object)) {
      result.set(originalName(gltf, object), object)
    }
  })
  return result
}

/* Return the direction faced by the door of the given rack in world coordinates.
 * Racks doors face +Z in racks local coordinates, racks of reversed rows are
 * rotated. */
function rackFront(rack: Object3D): Vector3 {
  const rotation = rack.getWorldQuaternion(new Quaternion())
  return new Vector3(0, 0, 1).applyQuaternion(rotation)
}

/* Return the bounding box center, size and radius of the racks of the
 * infrastructure, with the main direction faced by their doors. Racks represented
 * only because of other_racks drawing parameter are ignored, unless there is no
 * other rack. Fallback to the whole root if it does not contain racks. */
export function computeFocus(root: Object3D): Focus {
  root.updateMatrixWorld(true)
  const infrastructure = { box: new Box3(), front: new Vector3() }
  const all = { box: new Box3(), front: new Vector3() }
  root.traverse((object) => {
    if (object.userData?.category === 'rack') {
      const box = new Box3().setFromObject(object)
      const front = rackFront(object)
      all.box.union(box)
      all.front.add(front)
      if (object.userData.infrastructure !== false) {
        infrastructure.box.union(box)
        infrastructure.front.add(front)
      }
    }
  })
  let selected = infrastructure
  if (selected.box.isEmpty()) selected = all
  const box = selected.box.isEmpty() ? new Box3().setFromObject(root) : selected.box
  const center = box.getCenter(new Vector3())
  const size = box.getSize(new Vector3())
  // When racks face opposite directions in the same proportions, look at the
  // front of the room.
  const front = selected.front
  const azimuth = Math.hypot(front.x, front.z) > 1e-6 ? Math.atan2(front.x, front.z) : 0
  return { center, size, radius: Math.max(size.length() / 2, 0.5), azimuth }
}

/* Set anisotropic filtering of all textures in the scene, to keep floor tiles
 * sharp at grazing angles in the back of rooms. */
export function setTexturesAnisotropy(root: Object3D, anisotropy: number) {
  root.traverse((object) => {
    const mesh = object as Mesh
    if (!mesh.isMesh) return
    for (const material of [mesh.material].flat() as Material[]) {
      const map = (material as MeshStandardMaterial).map
      if (map) {
        map.anisotropy = anisotropy
        map.needsUpdate = true
      }
    }
  })
}

/* Dispose geometries, materials and textures of all objects under root. */
export function disposeObject(root: Object3D) {
  root.traverse((object) => {
    const mesh = object as Mesh
    if (mesh.geometry) mesh.geometry.dispose()
    if (mesh.material) {
      for (const material of [mesh.material].flat() as Material[]) {
        ;(material as MeshStandardMaterial).map?.dispose()
        material.dispose()
      }
    }
  })
}
